/* Nonproduction observation bridge. Validates existing Generic Practice snapshots without changing runtime.
   A local validated snapshot is not trusted server evidence or product eligibility approval. */
import {normalizePracticeLesson} from './practice-runtime-contract.js';
import {createPracticeCore} from './practice-runtime-core.js';
export function validateReceipt({saved,lesson,uid}){
 if(!uid||saved?.uid!==uid)return {status:'OWNER_MISMATCH'};
 if(saved?.phase!=='GENERIC_PRACTICE_V1'||saved.wire?.phase!=='complete')return {status:'NOT_COMPLETE'};
 try{const descriptor=normalizePracticeLesson(lesson);if(!descriptor||lesson.publisher!=='man'||saved.lessonId!==lesson.id||saved.lessonVersion!==lesson.version||saved.realizationId!==lesson.audioRealizationRef)return {status:'IDENTITY_MISMATCH'};
 const core=createPracticeCore(descriptor,{instanceId:saved.instanceId||'resume',attemptIndex:saved.attemptIndex||1});core.restore(saved.resumeIdentity,saved.coreState);
 const snapshot=core.snapshot();if(snapshot.phase!=='complete')return {status:'NOT_COMPLETE'};
 for(const field of ['phase','fullEnded','fullPlays','answer','correct','responseAssisted'])if(Object.hasOwn(snapshot,field)&&snapshot[field]!==saved.wire[field])return {status:'WIRE_MISMATCH'};
 return {status:'VALIDATED_LOCAL_PRACTICE',lessonId:lesson.id,version:lesson.version,instanceId:saved.instanceId||null,snapshot,eligibility:'PENDING_OWNER_DECISION',publicCredential:false};
 }catch{return {status:'INVALID_CORE_RECEIPT'};}
}
if(typeof window!=='undefined'&&window.ManBCSession){
 const storage={getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)};
 const journal=new ManLearningEvents.Journal({storage,locks:navigator.locks,uid:()=>currentUser?.uid||null,epoch:()=>ManWishlistHost.store.epoch()});
 const fixturePolicy=ManLearningEvents.OWNER_POLICY;
 const learning=new ManLearningEvents.Session({journal,bc:ManBCSession,catalog:()=>catalogUnitsCache,validateReceipt,policy:fixturePolicy});
 window.ManLearningSession=learning;
 const panelKeys={'man-mixed-panel':'man_mixed_panel_v1','man-inference-panel':'man_final_two_practice_v1','man-b02-panel':'man_batch02_practice_v1'};
 const capture=event=>{if(!event.isTrusted)return;const panel=event.target?.closest('#man-mixed-panel,#man-inference-panel,#man-b02-panel');if(!panel||panel.hidden)return;const keys=[panelKeys[panel.id]];const actor=window.ManWishlistHost.store.read();if(actor.status!=='LOCAL')return;
 setTimeout(()=>{const now=window.ManWishlistHost.store.read();if(now.uid!==actor.uid||now.epoch!==actor.epoch)return;
 let result={status:'NO_COMPLETED_PRACTICE',eligibility:'PENDING_OWNER_DECISION'};
 for(const key of keys){try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(!saved)continue;const lesson=catalogUnitsCache.find(u=>u.id===saved.lessonId);const candidate=validateReceipt({saved,lesson,uid:actor.uid});if(candidate.status==='VALIDATED_LOCAL_PRACTICE'){result={...candidate,observedUid:actor.uid};learning.acceptPractice({saved,lesson,context:actor,trustedSubmit:true}).then(status=>{const live=ManWishlistHost.store.read();if(live.uid===actor.uid&&live.epoch===actor.epoch){window.ManLearningEventStatus=status;if(status.sync?.ack)window.ManLearningRows={uid:actor.uid,epoch:actor.epoch,rows:status.sync.rows};xRenderMe();}}).catch(()=>{const live=ManWishlistHost.store.read();if(live.uid===actor.uid&&live.epoch===actor.epoch)window.ManLearningEventStatus={status:'UNAVAILABLE'};});break;}}catch{result={status:'STORAGE_UNAVAILABLE'};}}
 // RAM-only observation, no invented achievement event or historical backfill.
 window.ManBCPracticeObservation=result;
 },0);};
 const reviewKey=uid=>'man_review_attempt_v1_uid_'+uid;
 const previousReview=xRetrySaved;
 window.xRetrySaved=function(...args){const result=previousReview(...args);const actor=ManWishlistHost.store.read();if(actor.status==='LOCAL'&&isRetryMode){try{sessionStorage.setItem(reviewKey(actor.uid),JSON.stringify({schema:1,uid:actor.uid,attemptId:crypto.randomUUID()}));}catch{window.ManLearningEventStatus={status:'REVIEW_ATTEMPT_UNVERIFIABLE'};}}return result;};
 document.addEventListener('input',event=>{if(!event.isTrusted||event.target?.id!=='user-input'||!isRetryMode||isQuestionResolved)return;const actor=ManWishlistHost.store.read(),item=items[currentIndex];if(actor.status!=='LOCAL'||!item)return;let attempt;try{attempt=JSON.parse(sessionStorage.getItem(reviewKey(actor.uid))||'null');}catch{}
 setTimeout(()=>{const live=ManWishlistHost.store.read();if(live.uid!==actor.uid||live.epoch!==actor.epoch||!isRetryMode||!isQuestionResolved||!event.target.classList.contains('is-correct'))return;
 if(attempt?.uid!==actor.uid||!attempt.attemptId){window.ManLearningEventStatus={status:'REVIEW_ATTEMPT_UNVERIFIABLE'};return;}
 if(!item.segmentId||!item.audio?.lessonId||!item.audio?.lessonVersion){window.ManLearningEventStatus={status:'REVIEW_IDENTITY_UNVERIFIABLE'};return;}
 learning.acceptReview({context:actor,trustedResponse:true,receipt:{uid:actor.uid,lessonId:item.audio.lessonId,version:item.audio.lessonVersion,sentenceId:item.segmentId,attemptId:attempt.attemptId,reviewMode:true,revealed:false,outcome:'correct',at:Date.now()}}).then(status=>{const now=ManWishlistHost.store.read();if(now.uid===actor.uid&&now.epoch===actor.epoch){window.ManLearningEventStatus=status;if(status.sync?.ack)window.ManLearningRows={uid:actor.uid,epoch:actor.epoch,rows:status.sync.rows};xRenderMe();}}).catch(()=>{const now=ManWishlistHost.store.read();if(now.uid===actor.uid&&now.epoch===actor.epoch)window.ManLearningEventStatus={status:'UNAVAILABLE'};});
 },0);
 },true);
 document.addEventListener('submit',capture,true);
 auth.onAuthStateChanged(()=>{window.ManBCPracticeObservation=null;window.ManLearningEventStatus=null;window.ManLearningRows=null;const actor=ManWishlistHost.store.read();if(actor.status==='LOCAL'&&learning.admitted())Promise.resolve(loadCatalogUnits()).then(()=>{const now=ManWishlistHost.store.read();if(now.uid!==actor.uid||now.epoch!==actor.epoch)return null;return learning.recover();}).then(sync=>{if(!sync)return;const now=ManWishlistHost.store.read();if(now.uid===actor.uid&&now.epoch===actor.epoch){window.ManLearningEventStatus={status:sync.ack?'RECOVERED_LOCAL':sync.status,sync};if(sync.ack)window.ManLearningRows={uid:actor.uid,epoch:actor.epoch,rows:sync.rows};xRenderMe();}}).catch(()=>{});});
}

