/* Nonproduction host integration, loaded only by the bounded candidate. */
(function(){'use strict';
if(!window.ManWishlist)throw Error('WISHLIST_MODULE_REQUIRED');
let accountEpoch=0;
const store=new ManWishlist.Wishlist({storage:{getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v)},uid:()=>currentUser?.uid||null,catalog:()=>catalogUnitsCache||[],locks:navigator.locks,epoch:()=>accountEpoch});
let notice='';
function sync(){const view=store.read();XNOT.favorites=view.entries?.map(x=>({id:x.id,unitName:x.name}))||[];return view;}
function status(view){if(window.ManProductSync)return ManProductSync.status==='READY'?'Đã đối chiếu Để dành trong tài khoản thử nghiệm.':'Đang chờ đọc/lưu dữ liệu tài khoản; xem trạng thái đồng bộ.';return view.status==='GUEST'?'Đăng nhập để để dành bài theo tài khoản trên thiết bị này.':view.status==='LOCAL'?(navigator.onLine===false?'Đang ngoại tuyến · đã đọc dữ liệu trên thiết bị.':'Để dành trên thiết bị này · chưa đồng bộ giữa các máy.'):'Chưa đọc được Để dành. Dữ liệu cũ được giữ nguyên; thử tải lại.';}
function button(view,id){const saved=view.ids.includes(id);return `<button type="button" class="x-mini-btn" data-p2-wishlist="${xEsc(id)}" data-desired="${!saved}" aria-pressed="${saved}" ${view.status!=='LOCAL'||window.ManProductSync&&ManProductSync.status!=='READY'?'disabled':''}>${saved?'♥ Đã để dành':'♡ Để dành'}</button>`;}
function panel(){const view=sync(),el=document.getElementById('x-me-dashboard');if(!el)return;let node=document.getElementById('x-p2-wishlist');if(!node){node=document.createElement('section');node.id='x-p2-wishlist';node.className='x-panel';el.appendChild(node);}
 node.innerHTML=`<h3>❤️ Để dành (${view.ids?.length||0})</h3><p role="status">${xEsc(notice||status(view))}</p>${(view.entries||[]).map(e=>`<div><b>${xEsc(e.name)}</b> ${e.available?`<button type="button" class="x-mini-btn" data-p2-open="${xEsc(e.id)}">Mở bài</button>`:'<small>Bài hiện không có trong Kho đã tải; hãy tải lại Kho.</small>'}<button type="button" class="x-mini-btn" data-p2-wishlist="${xEsc(e.id)}" data-desired="false">Bỏ để dành</button></div>`).join('')||'<p>Chưa có bài để dành.</p>'}<button type="button" data-p2-refresh>Đọc lại Để dành</button>`;
}
const oldMe=xRenderMe;window.xRenderMe=function(){sync();oldMe();panel();};
const oldProgress=xRenderProgress;window.xRenderProgress=function(){sync();oldProgress();};
const oldCard=xLessonCard;window.xLessonCard=function(u){const html=oldCard(u);return !u.mine&&ManWishlist.official(u)?html.replace('</article>',button(store.read(),u.id)+'</article>'):html;};
function refresh(){xRenderMe();xRenderProgress();xRenderCarousel('catalog');if(typeof xLibMode!=='undefined'&&xLibMode==='catalog'&&!document.getElementById('x-library-modal')?.classList.contains('x-hidden'))xRenderLibrary();}
const messages={PENDING_STORAGE_DENIED:'Chưa lưu được bản chờ an toàn. Thao tác chưa được gửi; hãy cho phép lưu trữ rồi thử lại.',CLOUD_UNCONFIRMED:'Chưa xác nhận lưu tài khoản. Bản chờ riêng được giữ; xem đồng bộ để thử lại.',CLOUD_CONFLICT:'Tài khoản đã đổi trên thiết bị khác. Chưa ghi đè; chọn cách xử lý trong Đồng bộ.',CLOUD_LOADING:'Đang tải dữ liệu tài khoản. Thử lại sau khi tải xong.',DELETION_BLOCKED:'Đang xác nhận xử lý dữ liệu. Chưa thể thay đổi Để dành.',LOCAL:'Đã lưu trên thiết bị này.',CONFLICT:'Để dành đã đổi ở tab khác. Danh sách đã tải lại; chọn lại nếu cần.',UNAVAILABLE:'Chưa lưu được. Dữ liệu cũ được giữ nguyên; thử lại.',CONCURRENCY_UNAVAILABLE:'Trình duyệt chưa hỗ trợ lưu Để dành an toàn giữa các tab.',ACCOUNT_CHANGED:'Tài khoản đã đổi. Thao tác chưa được áp dụng cho tài khoản mới.',LESSON_UNAVAILABLE:'Bài chưa có trong Kho đã tải. Tải lại Kho trước khi lưu.',PARTIAL_ACK:'Đã lưu Để dành trên thiết bị; chưa xác nhận được evidence danh hiệu. Đừng suy ra danh hiệu từ thao tác này.',HISTORY_UNVERIFIABLE:'Đã lưu Để dành; chưa đủ mã phiên bản để ghi evidence danh hiệu.',PROOF_STORAGE_UNAVAILABLE:'Chưa đọc được evidence Để dành; thao tác chưa được ghi.',PROOF_LIMIT:'Đã lưu Để dành; evidence danh hiệu đã chạm giới hạn trên thiết bị.',RESPONSE_UNKNOWN:'Chưa xác nhận được kết quả lưu. Hãy đọc lại trước khi thử lại.'};
async function change(id,desired){const v=store.read();const context={uid:v.uid,token:v.token,epoch:v.epoch};const result=await (window.ManBCSession?window.ManBCSession.change(id,desired,context):store.setSaved(id,desired,context));if(currentUser?.uid!==v.uid)return;notice=result.cloud?.ack?'Đã lưu và đối chiếu tài khoản thử nghiệm.':messages[result.status]||status(result);refresh();xToast(notice);}
window.xFavoriteUnit=function(id){const view=store.read();return change(id,!view.ids.includes(id));};
document.addEventListener('click',async e=>{if(e.target.closest('[data-p2-refresh]')){notice='';refresh();return;}const b=e.target.closest('[data-p2-wishlist]');if(b){if(b.disabled)return;b.disabled=true;try{await change(b.dataset.p2Wishlist,b.dataset.desired==='true');}finally{b.disabled=false;}return;}const open=e.target.closest('[data-p2-open]');if(open){const view=store.read();if(!view.ids.includes(open.dataset.p2Open)||!view.entries.some(x=>x.id===open.dataset.p2Open&&x.available))return xToast('Bài không còn sẵn sàng.');xStartLessonChoice(false,open.dataset.p2Open,false);}});
window.addEventListener('storage',e=>{if(currentUser&&e.key===store.key(currentUser.uid)){notice='Danh sách đã cập nhật từ tab khác.';refresh();}});
for(const type of ['online','offline'])window.addEventListener(type,()=>{notice='';refresh();});
auth.onAuthStateChanged(()=>{accountEpoch++;notice='';refresh();});
document.addEventListener('DOMContentLoaded',refresh);
window.ManWishlistHost={store,refresh};
})();

assets.achievements.js:
/* Pure nonproduction derivation. Evidence must be admitted by an external trusted adapter.
   Structural validation here is NOT authentication, anti-cheat or a public credential authority. */
(function(g){'use strict';
const branches=[
 ['study','Học hành',[20,70,150,300],['Gương mặt mới toanh','Có dấu hiệu cao thủ','Chơi mà giấu nghề','Thua người bản xứ mỗi cái quốc tịch']],
 ['review','Không phục',[20,50,75],['Không phục','Chuyên gia gỡ gạc','Thù dai có ích']],
 ['affection','Tình củm',[1,10,10,50],['Ra mắt hàng xóm','Nhập tiệc','Gương mẫu trong xóm','Xứng đáng có 10 người iu']],
 ['days','Bền bỉ',[2,7,30],['Lại gặp nhau rồi','Có qua có lại','Khách quen trong xóm']]
];
const TITLES=Object.freeze(branches.flatMap(([branch,meaning,ns,names])=>ns.map((target,i)=>Object.freeze({id:branch+'-'+(i+1),branch,tier:i+1,name:names[i],target,meaning}))));
const id=x=>typeof x==='string'&&x.length>0&&x.length<=200;
const date=x=>typeof x==='string'&&Number.isFinite(Date.parse(x))&&/T.*(?:Z|[+-]\d\d:\d\d)$/.test(x);
const redacted=e=>e.verification==='UNVERIFIABLE'&&e.receipts.length===0;
const earnedValid=e=>TITLES.some(t=>t.id===e.id)&&Array.isArray(e.receipts)&&(redacted(e)||e.receipts.length>0&&e.receipts.every(id)&&e.verification===undefined);
function localDate(x){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(x));}
function evaluate({uid,evidence,wishlist,previous,policy={}}){
 if(!id(uid))throw Error('UID_REQUIRED');
 if(evidence?.uid!==uid||evidence?.schema!==1||!Array.isArray(evidence.events)||evidence.admission!=='VERIFIED_ADAPTER'||!id(evidence.summaryReceipt))throw Error('UNVERIFIED_EVIDENCE');
 if(wishlist?.uid!==uid||!Array.isArray(wishlist.ids))throw Error('WISHLIST_OWNER');
 if(previous&&(previous.uid!==uid||previous.schema!==1||!Array.isArray(previous.earned)))throw Error('STATE_OWNER_OR_SCHEMA');
 const known=new Set(TITLES.map(t=>t.id));
 if(previous?.earned.some(e=>!known.has(e.id)||!earnedValid(e)))throw Error('INVALID_EARNED_STATE');
 const official=new Set(evidence.officialLessonIds||[]),seen=new Map(),accepted=[], rejected=[];
 for(const e of evidence.events){
  const valid=e&&e.uid===uid&&id(e.eventId)&&id(e.receiptId)&&e.eligible===true&&date(e.at)&&['complete','active-review','practice','save','profile-saved'].includes(e.kind);
  const lessonValid=e?.kind==='profile-saved'||(official.has(e?.lessonId)&&id(e?.version));
  if(!valid||!lessonValid||(e.kind==='active-review'&&!id(e.sentenceId))||(e.kind==='profile-saved'&&e.nicknameSaved!==true)){rejected.push(e?.eventId||null);continue;}
  const signature=JSON.stringify([e.uid,e.kind,e.lessonId,e.version,e.sentenceId||null,e.at,e.receiptId,e.nicknameSaved||false]);
  if(seen.has(e.eventId)){if(seen.get(e.eventId)!==signature)throw Error('EVENT_ID_CONFLICT');continue;}seen.set(e.eventId,signature);accepted.push(e);
 }
 const completions=new Set(accepted.filter(e=>e.kind==='complete').map(e=>e.lessonId));
 const reviews=new Set(accepted.filter(e=>e.kind==='active-review').map(e=>e.lessonId+':'+e.sentenceId));
 const dates=new Set(accepted.filter(e=>e.kind==='practice').map(e=>localDate(e.at)));
 const saved=new Set(wishlist.ids.filter(x=>official.has(x)));
 const saves=accepted.filter(e=>e.kind==='save');
 const pairs=new Set(accepted.filter(e=>e.kind==='complete'&&saves.some(s=>s.lessonId===e.lessonId&&(policy.savedBeforeCompletion!==true||Date.parse(s.at)<Date.parse(e.at))&&(!policy.requireChronologyProof||(s.version===e.version&&e.saveReceiptId===s.receiptId)))).map(e=>e.lessonId));
 const nickname=accepted.some(e=>e.kind==='profile-saved');
 const old=new Map((previous?.earned||[]).map(e=>[e.id,{...e,receipts:[...e.receipts]}]));
 const rows=TITLES.map(t=>{
  let value=0,reason=null,qualifies=false;
  if(t.branch==='study')value=completions.size;
  else if(t.branch==='review')value=reviews.size;
  else if(t.branch==='days')value=dates.size;
  else if(t.id==='affection-1')value=nickname?1:0;
  else if(t.id==='affection-2'){value=saved.size;if(!completions.size)reason='COMPLETED_LESSON_REQUIRED';}
  else {value=pairs.size;if(typeof policy.savedBeforeCompletion!=='boolean')reason='SAVED_CHRONOLOGY_UNDECIDED';}
  qualifies=!reason&&value>=t.target;
  if(qualifies&&!old.has(t.id)){
   const relevant=accepted.filter(e=>t.branch==='study'?e.kind==='complete':t.branch==='review'?e.kind==='active-review':t.branch==='days'?e.kind==='practice':t.id==='affection-1'?e.kind==='profile-saved':['complete','save'].includes(e.kind));
   old.set(t.id,{id:t.id,receipts:[...new Set(relevant.map(e=>e.receiptId))]});
  }
  const earned=old.has(t.id);
  const deleted=earned&&redacted(old.get(t.id));return {...t,value:Math.min(value,t.target),progress:`${Math.min(value,t.target)}/${t.target}`,status:deleted?'UNVERIFIABLE':earned?'EARNED':reason?'UNVERIFIABLE':'LOCKED',reason:deleted?'HISTORY_EVIDENCE_DELETED':earned?null:reason};
 });
 const equipped=previous?.equipped&&old.has(previous.equipped)?previous.equipped:null;
 return {rows,rejected,state:{schema:1,uid,earned:[...old.values()],equipped}};
}
function equip(state,titleId){if(!state||state.schema!==1||!id(state.uid)||!TITLES.some(t=>t.id===titleId)||!state.earned?.some(e=>e.id===titleId&&!redacted(e)))throw Error('TITLE_NOT_EARNED');return {...state,earned:state.earned.map(e=>({...e,receipts:[...e.receipts]})),equipped:titleId};}
class Store {
 constructor({storage,uid,locks,epoch=()=>0}){Object.assign(this,{storage,uid,locks,epoch});}
